def scrub(text):
    """Redact strong credentials and authorization values without logging them."""
    value = str(text)
    for pattern in (r"\bhf_[A-Za-z0-9]+\b", r"\bsk-[A-Za-z0-9_-]{24,}\b",
                    r"\bAKIA[0-9A-Z]{16}\b", r"(?i)\bBearer\s+[A-Za-z0-9._~+/=-]+",
                    r"(?im)\bauthorization\s*[:=]\s*[^\r\n]+",
                    r"(?is)-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----.*?(?:-----END (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----|\Z)"):
        value = re.sub(pattern, "[REDACTED_SECRET]", value)
    return value


