def file_hash(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for block in iter(lambda: f.read(4 * 1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def finite_or_none(value):
    """Return finite numeric values unchanged and preserve missing data as ``None``.

    NaN and infinities are not valid JSON measurements. They are never coerced to
    zero because zero is evidence; non-finite values represent unavailable/invalid
    measurement. Booleans are deliberately left untouched.
    """
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, (int, float)):
        return value if math.isfinite(float(value)) else None
    return value


def sanitize_json_numbers(value):
    """Recursively replace non-finite numeric values with ``None`` for JSON contracts."""
    # Generated by GitHub Copilot - Oct-05-2026
    if isinstance(value, dict):
        changed = {}
        for key, item in value.items():
            clean = sanitize_json_numbers(item)
            if clean is not item or not isinstance(key, str):
                changed[str(key)] = clean
        if not changed and all(isinstance(key, str) for key in value):
            return value
        return {str(key): changed.get(str(key), item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        replacements = {}
        for index, item in enumerate(value):
            clean = sanitize_json_numbers(item)
            if clean is not item:
                replacements[index] = clean
        if not replacements and isinstance(value, list):
            return value
        return [replacements.get(index, item) for index, item in enumerate(value)]
    # numpy scalars expose item(); avoid importing numpy in the core module.
    if not isinstance(value, (str, bytes, bool, int, float, type(None))) and hasattr(value, "item"):
        try:
            return sanitize_json_numbers(value.item())
        except (ValueError, TypeError):
            pass
    return finite_or_none(value)


