def write_json(path, data):
    """Stream finite JSON atomically with unique temporary files and explicit cleanup."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    clean = sanitize_json_numbers(data)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=path.parent,
                                         prefix=path.name + ".", suffix=".tmp", delete=False) as handle:
            temporary = Path(handle.name)
            encoder = json.JSONEncoder(ensure_ascii=False, separators=(",", ":"), allow_nan=False, default=str)
            for chunk in encoder.iterencode(clean):
                handle.write(chunk)
            handle.flush()
            os.fsync(handle.fileno())
        temporary.replace(path)
    finally:
        if temporary:
            temporary.unlink(missing_ok=True)


