def overlap(a, b, c, d):
    return max(0.0, min(b, d) - max(a, c))


def stamp(t, srt=False):
    n = max(0, round(float(t) * 1000))
    h, n = divmod(n, 3600000)
    m, n = divmod(n, 60000)
    s, ms = divmod(n, 1000)
    sep = "," if srt else "."
    return f"{h:02}:{m:02}:{s:02}{sep}{ms:03}"


# Generated by GitHub Copilot - Oct-05-2026
def terminate_process_tree(process):
    """Reap owned subprocess trees after cancellation or timeout, without elevation."""
    if process.poll() is not None:
        return
    if os.name == 'nt':
        subprocess.run(['taskkill','/PID',str(process.pid),'/T','/F'],
                       stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,shell=False,timeout=10)
    else:
        import signal
        try:
            os.killpg(process.pid,signal.SIGTERM)
        except ProcessLookupError:
            pass
    try:
        process.wait(timeout=3)
    except subprocess.TimeoutExpired:
        process.kill()
        process.wait()


