def run_command(args, logger=None, *, timeout=7200, output_limit_bytes=8 * 1024 ** 2):
    """Bound subprocess time and output memory; untrusted arguments never become shell code."""
    command=[str(argument) for argument in args]
    flags=subprocess.CREATE_NEW_PROCESS_GROUP if os.name=='nt' else 0
    with tempfile.TemporaryFile() as stdout, tempfile.TemporaryFile() as stderr:
        with subprocess.Popen(command,stdout=stdout,stderr=stderr,shell=False,
                              creationflags=flags,start_new_session=os.name!='nt') as process:
            try:
                process.wait(timeout=timeout)
            except BaseException:
                terminate_process_tree(process)
                raise
            stdout_size,stderr_size=stdout.tell(),stderr.tell()
            if stdout_size>output_limit_bytes or stderr_size>output_limit_bytes:
                raise RuntimeError('Saida externa excedeu o limite de memoria; nao sera interpretada parcialmente.')
            stdout.seek(0)
            stderr.seek(0)
            out=stdout.read().decode('utf-8','replace')
            err=stderr.read().decode('utf-8','replace')
            if process.returncode:
                raise RuntimeError(scrub(err[-4500:] or out[-4500:]))
    return out,err


def versions():
    out = {}
    for package in ["numpy", "opencv-contrib-python", "opencv-python", "opencv-python-headless", "faster-whisper",
                    "ctranslate2", "scenedetect", "pyannote.audio", "torch", "torchaudio", "torchcodec",
                    "soundfile", "mediapipe", "ultralytics", "pytesseract", "panns-inference", "yt-dlp"]:
        try:
            out[package] = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            pass
    return out


class Unavailable(RuntimeError):
    pass


def ok(data, status="ok", notes=None, artifacts=None):
    return {"status": status, "data": data, "notes": notes or [],
            "artifacts": [str(Path(p).resolve()) for p in (artifacts or [])]}


@dataclass
class Context:
    video: Path
    output: Path
    config: dict
    signature: str
    logger: logging.Logger
    force: bool = False
    states: dict = field(default_factory=dict)
    issues: list = field(default_factory=list)
    stage_metrics: dict = field(default_factory=dict)

    @property
    def cache(self):
        p = self.output / "cache" / self.signature[:16]
        p.mkdir(parents=True, exist_ok=True)
        return p

    def step(self, name, params, call, *, required=False, code_files=None, output_version="2.0", requires=None):
        """Execute a resumable stage.

        ``code_files`` scopes cache invalidation to the implementation that actually
        affects this stage.  The v1 engine hashed every module for every stage, so an
        editorial-only code change invalidated ASR and vision caches.  Keeping the
        default preserves compatibility for third-party callers, while the v2 pipeline
        passes explicit module names.
        """
        module_dir = Path(__file__).parent
        requires = list(requires or [])
        blockers = []
        for dependency in requires:
            state = self.states.get(dependency, {})
            if state.get("status") in ("failed", "unavailable", "blocked", "cancelled"):
                blockers.append({"stage": dependency, "status": state.get("status")})
        if blockers:
            reason = ", ".join(f"{b['stage']}={b['status']}" for b in blockers)
            result = ok({}, "blocked", [f"blocked_by: {reason}"])
            key = digest({"version": __version__, "output_version": output_version,
                          "input": self.signature, "blocked_by": blockers, "params": params})
            result.update(key=key, input_hash=self.signature, config_hash=digest(params),
                          output_version=output_version, elapsed_seconds=0.0, blocked_by=blockers)
            checkpoint = self.cache / (name + ".json")
            write_json(checkpoint, result)
            self.states[name] = {"key": key, "status": "blocked", "blocked_by": blockers}
            self._notes(name, result)
            self.logger.warning("%s: blocked (%s)", name, reason)
            return {}
        if code_files:
            selected = []
            for value in code_files:
                candidate = Path(value)
                if not candidate.is_absolute():
                    candidate = module_dir / candidate
                if candidate.suffix != ".py":
                    candidate = candidate.with_suffix(".py")
                if candidate.is_file():
                    selected.append(candidate)
            code = {p.name: file_hash(p) for p in selected}
        else:
            code = {p.name: file_hash(p) for p in module_dir.glob("*.py")}
        config_hash = digest(params)
        # Generated by GitHub Copilot - Oct-05-2026
        from .run_status import DEPENDENCIES, STAGE_PACKAGES
        dependencies = {dependency: self.states[dependency] for dependency in DEPENDENCIES.get(name, requires)
                if dependency in self.states}
        package_versions = versions()
        scoped_versions = {package: version for package, version in package_versions.items()
                   if package in STAGE_PACKAGES.get(name, set())}
        key = digest({"cache_contract": "4.2", "output_version": output_version,
                  "code": code, "input": self.signature,
                  "dependencies": dependencies, "versions": scoped_versions, "params": params})
        checkpoint = self.cache / (name + ".json")
        if checkpoint.exists() and not self.force:
            try:
                cached = read_json(checkpoint)
                if cached["key"] == key and cached["status"] in ("ok", "partial", "skipped") and cached.get("data_checksum") == digest(cached["data"]) and all(
                    Path(p).is_file() for p in cached.get("artifacts", [])
                ):
                    self.logger.info("%s: retomado do cache", name)
                    self.states[name] = {"key": key, "status": cached["status"]}
                    self.stage_metrics[name] = {"cache_hit": True, "elapsed_seconds": 0.0,
                                                "original_elapsed_seconds": cached.get("elapsed_seconds")}
                    self._notes(name, cached)
                    return cached["data"]
            except (ValueError, KeyError, OSError):
                pass
        started = time.monotonic()
        self.logger.info("%s: iniciando", name)
        try:
            result = call()
        except (KeyboardInterrupt, SystemExit):
            raise
        except Unavailable as exc:
            if required or self.config["strict"]:
                raise RuntimeError(f"Falha em {name}: {scrub(exc)}") from exc
            result = ok({}, "unavailable", [scrub(exc)])
        except Exception as exc:
            tb = scrub("".join(traceback.format_exception(type(exc), exc, exc.__traceback__)))
            diagnostic = {
                "run_id": self.signature[:16], "stage": name, "exception_type": type(exc).__name__,
                "message": scrub(exc), "traceback": tb, "input": str(self.video),
                "config_hash": config_hash, "last_checkpoint": next(reversed(self.states), None),
            }
            logs = self.output / "logs"
            logs.mkdir(parents=True, exist_ok=True)
            with (logs / "technical_errors.jsonl").open("a", encoding="utf-8") as handle:
                handle.write(json.dumps(sanitize_json_numbers(diagnostic), ensure_ascii=False) + "\n")
            self.logger.error("%s failed with %s\n%s", name, type(exc).__name__, tb)
            if required or self.config["strict"]:
                raise RuntimeError(f"Falha em {name}: {scrub(exc)}") from exc
            result = ok({}, "failed", [scrub(exc)])
            result["error"] = {k: diagnostic[k] for k in ("exception_type", "message", "config_hash", "last_checkpoint")}
        result.update(key=key, input_hash=self.signature, config_hash=config_hash,
                      output_version=output_version,
                  data_checksum=digest(result["data"]),
                      elapsed_seconds=round(time.monotonic() - started, 3))
        write_json(checkpoint, result)
        self.states[name] = {"key": key, "status": result["status"]}
        self.stage_metrics[name] = {"cache_hit": False, "elapsed_seconds": result["elapsed_seconds"]}
        self._notes(name, result)
        self.logger.info("%s: %s (%.1fs)", name, result["status"], result["elapsed_seconds"])
        return result["data"]

    def _notes(self, name, result):
        for note in result.get("notes", []):
            self.issues.append({"stage": name, "status": result["status"], "message": note})
            self.logger.warning("%s: %s", name, note)


@contextmanager
# Generated by GitHub Copilot - Oct-05-2026
def output_lock(output):
    """Acquire an exclusive run lock; recover only a verified dead owner."""
    output = Path(output)
    output.mkdir(parents=True, exist_ok=True)
    lock = output / "RUNNING.lock"
    try:
        fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
    except FileExistsError:
        try:
            owner=int(lock.read_text(encoding='utf-8').strip())
        except (OSError,ValueError):
            owner=None
        if owner and not process_alive(owner):
            lock.unlink()
            try:
                fd=os.open(lock,os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            except FileExistsError:
                raise RuntimeError('Outra execucao adquiriu o lock durante a retomada.')
        else:
            raise RuntimeError(f"Já existe RUNNING.lock em {output}. Feche a execução anterior. "
                               "Lock desconhecido/corrompido exige revisao manual antes de remover.")
    try:
        with os.fdopen(fd,'w',encoding='ascii') as handle:
            handle.write(str(os.getpid()))
            handle.flush()
            os.fsync(handle.fileno())
        yield
    finally:
        lock.unlink(missing_ok=True)


# Generated by GitHub Copilot - Oct-05-2026
def process_alive(pid):
    """Check PID existence without os.kill(pid,0), which is unsafe on Windows."""
    if pid <= 0:
        return True
    if os.name=='nt':
        import ctypes
        from ctypes import wintypes
        kernel=ctypes.WinDLL('kernel32',use_last_error=True)
        kernel.OpenProcess.argtypes=(wintypes.DWORD,wintypes.BOOL,wintypes.DWORD)
        kernel.OpenProcess.restype=wintypes.HANDLE
        kernel.CloseHandle.argtypes=(wintypes.HANDLE,)
        kernel.GetExitCodeProcess.argtypes=(wintypes.HANDLE,ctypes.POINTER(wintypes.DWORD))
        handle=kernel.OpenProcess(0x1000,False,pid)
        if not handle:
            return ctypes.get_last_error()!=87
        try:
            code=wintypes.DWORD()
            return not kernel.GetExitCodeProcess(handle,ctypes.byref(code)) or code.value==259
        finally:
            kernel.CloseHandle(handle)
    try:
        os.kill(pid,0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


