@contextmanager
def logging_session(logger):
    """Close all owned log handles even when a stage or lock acquisition fails."""
    try:
        yield logger
    finally:
        for handler in list(logger.handlers):
            handler.close()
            logger.removeHandler(handler)


def setup_logging(output):
    logs = Path(output) / "logs"
    logs.mkdir(parents=True, exist_ok=True)
    logger = logging.getLogger("ldporto."+str(Path(output).resolve()))
    logger.setLevel(logging.INFO)
    for handler in list(logger.handlers):
        handler.close()
        logger.removeHandler(handler)
    fmt = SecretSafeFormatter("%(asctime)s %(levelname)s %(message)s", "%H:%M:%S")
    for handler in [logging.StreamHandler(),
                    logging.FileHandler(logs / "analyzer.log", encoding="utf-8")]:
        handler.setFormatter(fmt)
        logger.addHandler(handler)
    return logger


